<?phpnamespace ADMIN\AdminBundle\Entity;use Doctrine\ORM\Mapping as ORM;/** * ConsultaPersonaObservada * * @ORM\Entity * @ORM\Table("AUDITORIACNRTPERSONA") */class AuditoriaCnrtPersona{    /**     * @var integer     *     * @ORM\Column(name="ID", type="integer")     * @ORM\Id     * @ORM\GeneratedValue(strategy="SEQUENCE")     * @ORM\SequenceGenerator(sequenceName="AUDITORIACNRTPERSONA_ID_SEQ", allocationSize=1, initialValue=1)     */    private $id;        /**     * Many AuditoriaCnrtPersona has One CnrtPersona     *     * @ORM\ManyToOne(targetEntity="\ADMIN\AdminBundle\Entity\CnrtPersona"))     * @ORM\JoinColumn(name="CNRTPERSONAID", referencedColumnName="ID_CNRT", nullable=false)     **/    private $cnrtPersona;        /**     * @var string     *     * @ORM\Column(name="ACCION", type="blob", nullable=true)     */    private $accion;        /**     * Many AuditoriaCnrtPersona has One Usuario     *     * @ORM\ManyToOne(targetEntity="\SEGURIDAD\SeguridadBundle\Entity\Usuario"))     * @ORM\JoinColumn(name="USUALTAID", referencedColumnName="USUARIOID", nullable=false)     **/    private $usuAlta;        /**     * @var \DateTime     *     * @ORM\Column(name="FECALTA", type="datetime", nullable=true)     */    private $fecAlta;            /**     * Get id     *     * @return integer     */    public function getId()    {        return $this->id;    }        /**     * Set accion     *     * @param string $accion     * @return AuditoriaCnrtPersona     */    public function setAccion($accion)    {        $this->accion = $accion;                return $this;    }        /**     * Get accion     *     * @return string     */    public function getAccion()    {        if(is_resource($this->accion)){            return stream_get_contents($this->accion);        }else{            return $this->accion;        }    }        /**     * Set fecAlta     *     * @param \DateTime $fecAlta     * @return AuditoriaCnrtPersona     */    public function setFecAlta($fecAlta)    {        $this->fecAlta = $fecAlta;                return $this;    }        /**     * Get fecAlta     *     * @return \DateTime     */    public function getFecAlta()    {        return $this->fecAlta;    }            /**     * @return \ADMIN\AdminBundle\Entity\CnrtPersona     */    public function getCnrtPersona()    {        return $this->cnrtPersona;    }        /**     * @param \ADMIN\AdminBundle\Entity\CnrtPersona $cnrtPersona     * @return AuditoriaCnrtPersona     */    public function setCnrtPersona($cnrtPersona)    {        $this->cnrtPersona = $cnrtPersona;                return $this;    }        /**     * Set usualta     *     * @param \SEGURIDAD\SeguridadBundle\Entity\Usuario $usuario     * @return AuditoriaCnrtPersona     */    public function setUsuAlta(\SEGURIDAD\SeguridadBundle\Entity\Usuario $usuario)    {        $this->usuAlta = $usuario;                return $this;    }        /**     * Get usualta     *     * @return \SEGURIDAD\SeguridadBundle\Entity\Usuario     */    public function getUsuAlta()    {        return $this->usuAlta;    }    }